import csv
import io
import json

def process(data):
    text = data["selection"]
    if not text:
        raise ValueError("CSV input is empty")

    try:
        rows = list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except csv.Error as error:
        raise ValueError(f"Invalid CSV: {error}") from error

    if not rows or not rows[0]:
        raise ValueError("CSV header row is missing")

    headers = rows[0]
    if headers[0].startswith("\ufeff"):
        headers[0] = headers[0][1:]
    if any(header == "" for header in headers):
        raise ValueError("CSV headers cannot be empty")
    if len(set(headers)) != len(headers):
        raise ValueError("Duplicate CSV headers")

    result = []
    for index, row in enumerate(rows[1:], start=2):
        if len(row) != len(headers):
            raise ValueError(
                f"CSV row {index} has {len(row)} fields; expected {len(headers)}"
            )
        result.append(dict(zip(headers, row)))

    return json.dumps(result, ensure_ascii=False, indent=2)
